  let pos = in.c0.xyz;
  let n = fx_fbm3(pos * 2.3 + 1.7);
  let crack = pow(max(0.0, 1.0 - abs(n - 0.5) * 9.0), 1.5);
  let pulse = 0.8 + 0.2 * sin(time * 9.0 + pos.x * 6.0);
  let f = max(dot(normalize(in.normal), normalize(g.cam_pos.xyz - in.world)), 0.0);
